const fs = require('fs');
const JSZip = require('jszip');

async function main() {
  const data = fs.readFileSync('/workspace/testbed/docs/travel_summary.docx');
  const zip = await JSZip.loadAsync(data);
  let content = await zip.file('word/document.xml').async('string');

  // Update BK-B70889: route from ' → ' to 'JFK → LHR' and status from 'confirmed' to 'Scheduled'
  const oldText = 'Booking BK-B70889 | user_59b22691 |  →  | business | Status: confirmed | \$1180';
  const newText = 'Booking BK-B70889 | user_59b22691 | JFK → LHR | business | Status: Scheduled | \$1180';

  if (!content.includes(oldText)) {
    console.log('ERROR: Could not find the expected text in document');
    process.exit(1);
  }

  content = content.replace(oldText, newText);
  zip.file('word/document.xml', content);

  const output = await zip.generateAsync({ type: 'nodebuffer' });
  fs.writeFileSync('/workspace/testbed/docs/travel_summary.docx', output);
  console.log('Document updated successfully');
}
main();
"

